/* bundle.js —— 由 _scripts/build-js-bundle.mjs 从 _scripts/js-bundle.manifest.json 生成。
 * 不要手改这个文件：改源码后重新跑 `node _scripts/build-js-bundle.mjs`。
 * 打包原因见脚本头注释（首屏 69 个请求 → 1 个）。
 */

/* ==== js/utils.js ==== */
/* utils.js —— 请求封装 / 格式化 / 节流 / 缓存 */

// JSONP：用于只给 callback 不给 CORS 头的接口（东财 searchapi）
function fetchJSONP(url, cbParam = 'cb', timeout = 8000) {
  return new Promise((resolve, reject) => {
    // 回调名不能以下划线开头：新浪 roll 接口会拒绝（"callback illegal character"）
    const name = 'gfdcb' + Math.random().toString(36).slice(2, 10);
    const s = document.createElement('script');
    let done = false;
    const cleanup = (keepNoop) => {
      done = true;
      // 超时路径不能把回调真删掉：已发出的 <script> 稍后才到达时，会调用已删除的全局名
      // 抛未捕获 ReferenceError——留个空函数吸收迟到响应。成功/出错路径脚本已落幕，正常删。
      if (keepNoop) window[name] = () => {};
      else delete window[name];
      s.remove();
    };
    const timer = setTimeout(() => {
      if (!done) { cleanup(true); reject(new Error('jsonp timeout')); }
    }, timeout);
    window[name] = (data) => { clearTimeout(timer); cleanup(false); resolve(data); };
    s.onerror = () => { clearTimeout(timer); cleanup(false); reject(new Error('jsonp error')); };
    s.src = url + (url.includes('?') ? '&' : '?') + cbParam + '=' + name;
    document.head.appendChild(s);
  });
}

// 通用请求：直连 → window.PROXY 代理（重试一次）
async function request(url, { gbk = false, timeout = 10000 } = {}) {
  const tryFetch = async (u) => {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), timeout);
    try {
      if (gbk) {
        const res = await fetch(u, { signal: ctl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return new TextDecoder('gbk').decode(await res.arrayBuffer());
      }
      const res = await fetch(u, { signal: ctl.signal });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return await res.json();
    } finally { clearTimeout(timer); }
  };
  try { return await tryFetch(url); }
  catch (e) {
    if (!window.PROXY) throw e;
    return tryFetch(window.PROXY + '?url=' + encodeURIComponent(url));
  }
}

const throttle = (fn, ms) => {
  let t = 0;
  return (...a) => { const now = Date.now(); if (now - t > ms) { t = now; fn(...a); } };
};
const debounce = (fn, ms) => {
  let t;
  return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
};

// 缺失值判定：null / undefined / 空串 / 纯空白 / NaN / ±Infinity 一律算"没有数据"。
// 空串以前会被 isNaN 放过去（Number('') === 0），于是一个没填的格子会显示成 "0.00"——
// 那是在编数字。Infinity 同理（JSON.parse('1e400') 就能得到它）。
const isMissing = (v) => {
  if (v === null || v === undefined) return true;
  if (typeof v === 'string' && v.trim() === '') return true;
  return !Number.isFinite(Number(v));
};
const num = (v) => {
  if (v === null || v === undefined || v === '-') return null;
  if (typeof v === 'string' && v.trim() === '') return null;   // 纯空白 = 没填
  const n = Number(v);
  return Number.isFinite(n) ? n : null;   // Infinity / -Infinity 同样算缺失
};
const fmt = (n, d = 2) => isMissing(n) ? '--' : Number(n).toFixed(d);
const fmtPct = n => isMissing(n) ? '--' : (n > 0 ? '+' : '') + Number(n).toFixed(2) + '%';
const fmtChg = (n, d = 2) => isMissing(n) ? '--' : (n > 0 ? '+' : '') + Number(n).toFixed(d);
const fmtVol = n => {
  if (isMissing(n)) return '--';
  return n >= 1e8 ? (n / 1e8).toFixed(2) + '亿' : n >= 1e4 ? (n / 1e4).toFixed(0) + '万' : String(Math.round(n));
};
// 价格小数位：加密/外汇小价格要多位
const priceDigits = (p) => {
  if (isMissing(p)) return 2;
  const a = Math.abs(Number(p));
  if (a >= 1000) return 2;
  if (a >= 1) return 2;   // A股 7.28 显示 7.28（去尾零）；外汇第 4 位由市场分支（fx→4）负责
  if (a >= 0.01) return 4;
  return 6;
};
const fmtPrice = (p) => fmt(p, priceDigits(p));

const fmtTime = (ts) => {
  if (!ts) return '--';
  const d = new Date(ts);
  const p = (x) => String(x).padStart(2, '0');
  return p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds());
};
const fmtAgo = (ts) => {
  if (!ts) return '';
  const s = Math.floor((Date.now() - ts) / 1000);
  if (s < 60) return '刚刚';
  if (s < 3600) return Math.floor(s / 60) + ' 分钟前';
  if (s < 86400) return Math.floor(s / 3600) + ' 小时前';
  return Math.floor(s / 86400) + ' 天前';
};

// 本地日期（YYYY-MM-DD）。不用 toISOString——它按 UTC 取日期，
// 中国时区早上八点前会把当天记成昨天
const fmtDay = (ts) => {
  if (!ts) return '--';
  const d = new Date(ts);
  const p = (x) => String(x).padStart(2, '0');
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate());
};

const escapeHTML = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// 把"本地墙钟"编码成伪 UTC 秒级时间戳。
// lightweight-charts 对 UTCTimestamp 一律按 UTC 渲染：直接传真实 epoch 会让时间轴
// 平移一个时区（实测上证分时 09:30-15:00 显示成 02:00-07:00）。把墙钟分量用 Date.UTC
// 重新编码后，图表显示出来的就是用户本地时间。分时 / 分钟级 K线必用；日/周K用日期字符串不受影响。
function toChartTime(epochSec) {
  const d = new Date(epochSec * 1000);
  return Math.floor(Date.UTC(
    d.getFullYear(), d.getMonth(), d.getDate(),
    d.getHours(), d.getMinutes()
  ) / 1000);
}

// 内存缓存：最近一次成功数据（降级链兜底）。
// 关键前缀持久化到 localStorage：纯内存缓存刷新页面即清空，若此时主备源恰好都挂，
// 降级链最后一环等于不存在。持久化后跨会话仍有兜底（带时间戳，界面会标注缓存时间）。
const Cache = {
  _m: new Map(),
  // heat:us（美股全市场 ≈1.38 万行）持久化会同步字符串化 ~1.5MB 卡主线程、
  // 逼近 localStorage 5MB 配额（超了以后每次写入都静默失败），只留内存缓存；
  // heat:hk（~2900 行）与 lhb（日频 ~80 行）量级安全，照常持久化兜底。
  // heat:cn（A 股全市场 ≈5300 行）本来也在持久化名单里，字符串化约 913KB，
  // 而它每 30 秒就被重写一次 —— 光这一条就是每 30 秒往磁盘塞 913KB。
  // 它和 heat:us 是同一个量级问题，按同样的理由移出持久化（内存缓存照样有）。
  // events:/sb/brk/etf/fundholds/wbmacro 是各降级链的「静态 JSON → 缓存」最后一环
  // （gdelt/polymarket/南向/13F/ETF持股/世界银行，最大单 key ~80KB），刷新后仍可用；
  // crypto:cap 是加密流通市值富化（~250 条 [symbol,市值]，~10KB），旧市值仍比成交额代理诚实
  _persist: ['q:', 'heat:crypto', 'heat:hk', 'lhb', 'news', 'report:',
             'events:', 'sb', 'brk', 'etf', 'fundholds', 'wbmacro', 'crypto:cap'],
  _canPersist(key) { return this._persist.some(p => key.startsWith(p)); },

  // 落盘攒批：**只对行情缓存（q:）攒批**。
  // 一次行情刷新会写上百个 q:<symbol>，每个都同步 setItem 一次 =
  // 上百次同步磁盘写，主线程直接卡一下。行情缓存是「有更好、没有也能跑」的兜底，
  // 攒 250ms 再统一刷出去，不影响任何降级链。
  // 其余 key（events:/sb/brk/etf/fundholds/wbmacro/heat:hk/…）是各降级链的最后一环，
  // 必须**写完就落盘**——否则「刷新页面后仍然可用」这条承诺就破了。
  _pending: new Map(),
  _flushTimer: null,
  _queue(key, entry) {
    this._pending.set(key, entry);
    if (this._flushTimer) return;
    this._flushTimer = setTimeout(() => {
      this._flushTimer = null;
      const pending = this._pending;
      this._pending = new Map();
      for (const [k, e] of pending) {
        try { localStorage.setItem('gfd_cache_' + k, JSON.stringify(e)); }
        catch { /* 超配额时退化为纯内存缓存 */ }
      }
    }, 250);
  },
  set(key, val) {
    const e = { val, at: Date.now() };
    this._m.set(key, e);
    if (!this._canPersist(key)) return;
    if (key.startsWith('q:')) { this._queue(key, e); return; }
    try { localStorage.setItem('gfd_cache_' + key, JSON.stringify(e)); }
    catch { /* 超配额时退化为纯内存缓存 */ }
  },
  get(key, maxAge) {
    const e = this._m.get(key);
    if (!e) return null;
    if (maxAge && Date.now() - e.at > maxAge) return null;   // 过期视为未命中
    return e;
  },
  raw(key) {
    let e = this._m.get(key);
    if (!e && this._canPersist(key)) {
      try {
        e = JSON.parse(localStorage.getItem('gfd_cache_' + key));
        if (e && e.val !== undefined) this._m.set(key, e); else e = null;
      } catch { e = null; }
    }
    return e || null;
  },
};

// 折叠状态持久化的净化：把 localStorage 里读回的折叠表收敛成 {id:true}，
// 只留「值为 true 且 id 在现存分区名单里」的键。读回来的可能是任何脏值
// （手改、旧版本结构、JSON 损坏之外的合法垃圾），恢复前先净化——
// 思路与 zones.resolveZone 一致：非法值收敛回落，不抛错也不猜。
function sanitizeFolds(raw, validIds) {
  const out = {};
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return out;
  const valid = validIds || [];
  Object.keys(raw).forEach(k => {
    if (raw[k] === true && valid.indexOf(k) >= 0) out[k] = true;
  });
  return out;
}

window.U = {
  fetchJSONP, request, throttle, debounce,
  num, fmt, fmtPct, fmtChg, fmtVol, fmtPrice, priceDigits, fmtTime, fmtAgo, isMissing,
  escapeHTML, Cache, toChartTime, fmtDay, sanitizeFolds,
};
;

/* ==== js/focus-trap.js ==== */
/* focus-trap.js —— 弹层焦点工具（进焦点 / Tab 循环 / 退出还焦点）
 *
 * 为什么要有这一层：站里原本有三套各写各的弹层键盘处理——
 *   · app.js 的设置弹层：手写 Tab 循环，候选选择器漏了 <summary>，
 *     「开发者：数据源自检」那个折叠块永远拿不到焦点；
 *   · pmshare.js 的分享弹层：自己一份 Tab 陷阱；
 *   · alerts.js 的到价提醒弹层：根本没有陷阱，Tab 会跑进背景的 K 线页，
 *     关掉后焦点掉到 body，键盘用户直接迷路。
 * 三份各写各的 = 三份都会漏。现在合成一处：谁开弹层谁调 FocusTrap.open()，
 * 关的时候调 close()，焦点自己还回去。
 *
 * 约定：
 *   · open(root, opts) —— root 是弹层根节点，opts.initialFocus 指定先进哪个，
 *     opts.onEscape 收 Esc（不传就只拦 Tab）；
 *   · close() —— 解除 Tab 循环，并把焦点还给开弹层前的那一个。
 * 全站同时只允许一个陷阱：后开的接管先开的（嵌套弹层本来也只会有一个）。
 */
const FocusTrap = (() => {
  /* 候选：能拿到键盘焦点的都算上。
     <summary> 必须在里面——<details> 的折叠头是原生可聚焦的，
     漏了它设置弹层里的「数据源自检」就打不开。 */
  const FOCUSABLE = [
    'a[href]', 'button', 'input', 'select', 'textarea', 'summary',
    '[tabindex]:not([tabindex="-1"])',
  ].join(', ');

  let session = null;   // 当前生效的陷阱

  /* 弹层里真正能聚焦的元素：排除 disabled、排除隐藏的（display:none 的祖先）。
     用 getClientRects 判断可见性，比 offsetParent 稳（fixed 定位的元素 offsetParent 是 null）。 */
  function focusables(root) {
    if (!root || !root.querySelectorAll) return [];
    const list = root.querySelectorAll(FOCUSABLE);
    return Array.prototype.slice.call(list || []).filter(el => {
      if (!el || el.disabled) return false;
      if (el.getAttribute && el.getAttribute('aria-hidden') === 'true') return false;
      if (typeof el.getClientRects === 'function') return el.getClientRects().length > 0;
      return true;
    });
  }

  function onKeydown(e) {
    const root = session && session.root;
    if (!root) return;
    if (e.key === 'Escape') {
      if (session.onEscape) {
        // Esc 只关最上面那层：拦下来，别让下层弹层/详情页跟着反应
        if (e.preventDefault) e.preventDefault();
        if (e.stopPropagation) e.stopPropagation();
        session.onEscape();
      }
      return;
    }
    if (e.key !== 'Tab') return;
    const f = focusables(root);
    if (!f.length) { e.preventDefault(); return; }
    const first = f[0], last = f[f.length - 1];
    const act = document.activeElement;
    const inside = !!(act && root.contains && root.contains(act));
    if (e.shiftKey) {
      if (!inside || act === first) { e.preventDefault(); last.focus(); }
    } else if (!inside || act === last) {
      e.preventDefault(); first.focus();
    }
  }

  /* 收掉当前陷阱。restore=false 时不还焦点——开新弹层时用：
     那时要把焦点还给**新**弹层的触发点，不能被上一个陷阱抢回去。 */
  function teardown(restore) {
    const s = session;
    if (!s) return;
    session = null;
    if (document.removeEventListener) document.removeEventListener('keydown', onKeydown, true);
    if (restore && s.lastFocus && s.lastFocus.focus &&
        (!document.contains || document.contains(s.lastFocus))) {
      try { s.lastFocus.focus(); } catch (err) { /* 触发点已消失，忽略 */ }
    }
  }

  /**
   * 开一个焦点陷阱。
   * @param {HTMLElement} root 弹层根节点
   * @param {{initialFocus?: HTMLElement, onEscape?: Function}} opts
   * @returns {{close: Function}} 句柄
   */
  function open(root, opts) {
    if (!root) return { close: () => {} };
    const o = opts || {};
    const act = document.activeElement;
    teardown(false);   // 同一时刻只留一个陷阱（但不还焦点，见上面的说明）
    session = {
      root,
      onEscape: o.onEscape || null,
      // 记住是谁打开的：关掉之后焦点回到那儿，键盘用户不丢位置
      lastFocus: (act && act !== document.body && act.focus) ? act : null,
    };
    // 捕获阶段：Tab 循环要在别的监听器之前收口
    if (document.addEventListener) document.addEventListener('keydown', onKeydown, true);
    const first = o.initialFocus || focusables(root)[0];
    if (first && first.focus) { try { first.focus(); } catch (err) { /* 元素已移除，忽略 */ } }
    return { close };
  }

  /** 关掉陷阱：解除监听 + 把焦点还给开它的那个元素 */
  function close() {
    teardown(true);
  }

  return { open, close, focusables, isActive: () => !!session };
})();

window.FocusTrap = FocusTrap;
;

/* ==== js/store.js ==== */
/* store.js —— localStorage：自选 / 设置 */

const Store = {
  get(key, def) {
    try {
      const v = JSON.parse(localStorage.getItem('gfd_' + key));
      return v === null || v === undefined ? def : v;
    } catch { return def; }
  },
  set(key, val) {
    try { localStorage.setItem('gfd_' + key, JSON.stringify(val)); } catch { /* 隐私模式忽略 */ }
  },

  // 自选：统一存 { symbol, name, market }，symbol 跨市场唯一（sh600519 / usAAPL / BTCUSDT / EM:171.US10Y）
  watchlist: {
    all() { return Store.get('watchlist', []); },
    has(sym) { return this.all().some(x => x.symbol === sym); },
    toggle(item) {
      const a = this.all();
      const i = a.findIndex(x => x.symbol === item.symbol);
      if (i >= 0) { a.splice(i, 1); Store.set('watchlist', a); return false; }
      a.push({ symbol: item.symbol, name: item.name, market: item.market });
      Store.set('watchlist', a);
      return true;
    },
  },

  settings: {
    get() {
      // 默认主题 = 瑞士（白底红强调，用户 2026-10-18 指定）；老用户已存过设置的不受影响
      // academy：白话金融的科普入口（悬停「这是什么」+ 顶栏链接 + 详情页链接）
      return Object.assign(
        { updown: 'red', refresh: 10, showDegraded: true, theme: 'daylight', academy: true },
        Store.get('settings', {})
      );
    },
    set(s) { Store.set('settings', Object.assign(this.get(), s)); },
  },

  // 持仓跟踪（2026-10-18）：本机记账，行情 tick 里实时算市值/盈亏。
  // holding = { id, symbol, name, code, market, secid, shares, cost, createdAt }
  // cost 允许 null（用户没填成本价：只算市值，不算盈亏）
  portfolio: {
    all() { return Store.get('portfolio', []); },
    add(h) {
      const list = this.all();
      const rec = Object.assign({
        id: 'pf_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
        createdAt: Date.now(), secid: '', cost: null,
      }, h);
      list.push(rec);
      Store.set('portfolio', list);
      return rec;
    },
    update(id, patch) {
      const list = this.all();
      const i = list.findIndex(x => x.id === id);
      if (i < 0) return null;
      Object.assign(list[i], patch);
      Store.set('portfolio', list);
      return list[i];
    },
    remove(id) { Store.set('portfolio', this.all().filter(x => x.id !== id)); },
    symbols() { return this.all().map(x => x.symbol).filter(Boolean); },
  },

  // 组合总市值的每日快照（资产曲线）。value 为人民币口径；同日覆盖、上限 400 条
  portSnaps: {
    all() { return Store.get('portSnaps', []); },
    push(dateStr, value) {
      const list = this.all().filter(x => x && x.d && typeof x.v === 'number');
      const i = list.findIndex(x => x.d === dateStr);
      if (i >= 0) list[i] = { d: dateStr, v: value };
      else list.push({ d: dateStr, v: value });
      list.sort((a, b) => (a.d < b.d ? -1 : a.d > b.d ? 1 : 0));
      const trimmed = list.slice(-400);
      Store.set('portSnaps', trimmed);
      return trimmed;
    },
  },

  // 到价提醒（2026-09-17）：纯本地规则，行情 tick 里判定。
  // alert = { id, symbol, name, market, dir:'above'|'below', price, note,
  //           createdAt, triggeredAt:null, triggeredPrice:null }
  alerts: {
    all() { return Store.get('alerts', []); },
    active() { return this.all().filter(x => !x.triggeredAt); },
    add(a) {
      const list = this.all();
      const rec = Object.assign({
        id: 'al_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
        createdAt: Date.now(), triggeredAt: null, triggeredPrice: null, note: '',
      }, a);
      list.push(rec);
      Store.set('alerts', list);
      return rec;
    },
    remove(id) { Store.set('alerts', this.all().filter(x => x.id !== id)); },
    update(id, patch) {
      const list = this.all();
      const i = list.findIndex(x => x.id === id);
      if (i < 0) return null;
      Object.assign(list[i], patch);
      Store.set('alerts', list);
      return list[i];
    },
  },
};

window.Store = Store;
;

/* ==== js/proxy.js ==== */
/* proxy.js —— 代理前缀 + 数据源状态登记（降级角标用） */

// 部署到静态站且直连被墙时，把这里改成你的 Cloudflare Worker 地址：
// window.PROXY = 'https://your-worker.workers.dev/';
window.PROXY = window.PROXY || '';

// 数据源健康状态：记录每个逻辑源最近一次结果，供页脚 / 角标展示
const SourceState = {
  _m: new Map(),
  ok(key, via) { this._m.set(key, { ok: true, via: via || 'primary', at: Date.now() }); },
  fail(key, msg) {
    const prev = this._m.get(key) || {};
    this._m.set(key, { ok: false, via: prev.via || null, at: Date.now(), msg: String(msg || '') });
  },
  get(key) { return this._m.get(key) || null; },
  all() { return Array.from(this._m.entries()); },
};

window.SourceState = SourceState;
;

