/* ==== js/data/academy-gloss.js ==== */
/* academy-gloss.js —— 指向「白话金融 OpenFin Academy」的解释入口
   终端里鼠标靠近一个标的时，除了本站的一句话解释，再给一条去科普站读完整解释的路。

   纪律：链接必须诚实到"点进去就知道会看到什么"。
     · 精确页：这个符号的主体就是这个词（科创50 → 科创50 的解释）——点进去就是它自己。
     · 概念页：这个符号只是某个概念的一个代表（工商银行 → 股息/分红的解释）——文案里写出是哪个概念。
     · 搜索页：科普站没有这一页——只给"去科普站里搜这个词"，不做点进去扑空的假入口。
   宁可给搜索页，也不给一个主体对不上的页面。 */

const AcademyGloss = (() => {
  const BASE = 'https://5777-wq.github.io/openfin-academy/';

  // 精确页：symbol → 科普站术语 id
  const TERM_BY_SYMBOL = {
    // ---- A 股四大指数（各是各的，不许一律指到「A股」） ----
    'sh000001': 'sse-index',           // 上证指数
    'sz399001': 'szse-component',      // 深证成指
    'sz399006': 'chinext',             // 创业板指
    'sh000688': 'kechuang-50',         // 科创50
    // ---- 海外指数 ----
    'usIXIC': 'nasdaq',                // 纳斯达克
    'usINX': 'sp500',                  // 标普500
    'usDJI': 'dow-jones',              // 道琼斯
    'hkHSI': 'hsi',                    // 恒生指数
    'EM:100.N225': 'nikkei',           // 日经225
    'EM:100.GDAXI': 'dax',             // 德国DAX
    'EM:100.FTSE': 'ftse100',           // 英国富时100
    'EM:100.FCHI': 'cac40',             // 法国CAC40
    'EM:100.KS11': 'kospi',             // 韩国KOSPI
    'EM:100.SENSEX': 'sensex',         // 印度SENSEX
    // ---- 商品与汇率 ----
    'EM:101.GC00Y': 'gold',            // COMEX 黄金
    'EM:102.CL00Y': 'crude-oil',       // NYMEX 原油
    // ---- 加密：科普站只收了比特币与以太坊这两个词条 ----
    // 加密标的不在 TENCENT_UNIVERSE / EM_UNIVERSE 里，inUniverse 判不到，
    // 以前全都落到「去科普站搜这个币名」的搜索页——而本站搜不到「币安币」，
    // 点过去必然是「没有找到」。这里给有词条的两个精确页，其余不给链接。
    'BTCUSDT': 'btc',
    'ETHUSDT': 'eth',
    'EM:101.SI00Y': 'silver',          // COMEX 白银
    'EM:100.UDI': 'dollar-index',      // 美元指数
    // ---- 利率 ----
    'EM:171.US10Y': 'risk-free-rate',  // 美债10年：无风险利率本人
    // ---- 其余大宗商品：都是「大宗商品」这个词的代表 ----
    'EM:101.HG00Y': 'commodity',        // COMEX铜
    'EM:102.NG00Y': 'commodity',        // 天然气
    'EM:103.ZC00Y': 'commodity',        // 玉米
  };

  // 概念页：symbol → { id, name }——这个符号只是这个概念的一个代表
  const CONCEPT_BY_SYMBOL = {
    // 长端利率是"无风险利率"这个概念的代表（短端看的是曲线）
    'EM:171.US30Y': { id: 'risk-free-rate', name: '无风险利率' },
    'EM:171.CN10Y': { id: 'risk-free-rate', name: '无风险利率' },
    'EM:171.US2Y': { id: 'yield-curve', name: '收益率曲线' },
    'EM:171.US3M': { id: 'yield-curve', name: '收益率曲线' },
    'EM:171.US5Y': { id: 'yield-curve', name: '收益率曲线' },
    'EM:171.CN2Y': { id: 'yield-curve', name: '收益率曲线' },
    'EM:171.CN5Y': { id: 'yield-curve', name: '收益率曲线' },
    'EM:171.CN30Y': { id: 'yield-curve', name: '收益率曲线' },
    'EM:171.DE10Y': { id: 'yield-curve', name: '收益率曲线' },
    'EM:171.JP10Y': { id: 'yield-curve', name: '收益率曲线' },
    // 美元兑港币：联系汇率这个制度最典型的一对
    'EM:119.USDHKD': { id: 'fx-regime', name: '汇率制度' },
    // 外汇：科普站没有它们的月线序列，给「外汇」这个词条，不给半空的标的页
    'EM:119.EURUSD': { id: 'fx', name: '外汇' },
    'EM:119.GBPUSD': { id: 'fx', name: '外汇' },
    'EM:119.USDJPY': { id: 'fx', name: '外汇' },
    'EM:133.USDCNH': { id: 'fx', name: '外汇' },
    // 高股息标的：它们是"股息/分红"这个概念的代表
    'sh601398': { id: 'dividend', name: '股息 / 分红' },   // 工商银行
    'sh601288': { id: 'dividend', name: '股息 / 分红' },   // 农业银行
    'sh601988': { id: 'dividend', name: '股息 / 分红' },   // 中国银行
    'hk01398': { id: 'dividend', name: '股息 / 分红' },   // 工商银行（H）
    'hk00941': { id: 'dividend', name: '股息 / 分红' },   // 中国移动
    'hk00005': { id: 'dividend', name: '股息 / 分红' },   // 汇丰控股
    'hk00883': { id: 'dividend', name: '股息 / 分红' },   // 中国海洋石油
    'sh601088': { id: 'dividend', name: '股息 / 分红' },   // 中国神华
  };

  /**
   * 这次悬停该跳科普站的哪儿。
   * @param {string} symbol 行情 symbol（可空）
   * @param {string} name 标的名称
   * @returns {{href:string,kind:string,label:string}|null}
   */
  function targetFor(symbol, name) {
    const exact = TERM_BY_SYMBOL[symbol];
    if (exact) {
      return {
        href: BASE + '#/term/' + encodeURIComponent(exact),
        kind: 'exact',
        label: '在白话金融里看完整解释 ↗',
      };
    }
    const concept = CONCEPT_BY_SYMBOL[symbol];
    if (concept) {
      return {
        href: BASE + '#/term/' + encodeURIComponent(concept.id),
        kind: 'concept',
        label: '在白话金融里看「' + concept.name + '」的解释 ↗',
      };
    }
    // 标的百科页：终端 universe 里的每一只，科普站都**尽量**有同名的一页——
    // 但只给真的采到月线序列的那些（有专文的带讲解，没专文的至少带真实的
    // 峰谷数据卡）。科普站没有数据的那几只，给的是半空页，那属于假入口，
    // 不给：让它们落到概念页或搜索页去。
    // 「真的有页」的清单由 _scripts/collect-academy-terms.mjs 从科普站同步
    // （js/data/academy-assets.js），不在这里手抄——手抄的迟早对不上。
    if (inUniverse(symbol) && hasAssetPage(symbol)) {
      return {
        href: BASE + '#/assets/' + encodeURIComponent(symbol),
        kind: 'asset',
        label: '在白话金融里看这一页 ↗',
      };
    }
    // 搜索页兜底：**只有科普站真能搜到这个词时才给**。
    // 之前无条件给，于是像「谷歌-A」「强生」这类本站根本没有的词，
    // 点过去就是一条「没有找到」的死路——比不给链接更糟。
    const q = String(name || '').trim();
    if (!q) return null;
    if (!searchableOnAcademy(q)) return null;
    return {
      href: BASE + '#/search?q=' + encodeURIComponent(q),
      kind: 'search',
      label: '在白话金融里查「' + q + '」↗',
    };
  }

  /** 科普站真能搜到这个词吗？（清单由 collect-academy-terms.mjs 从科普站同步）
      清单没加载进来时保守地不给——宁可没有入口，也不要一条死路。 */
  let searchSet = null;
  function searchableOnAcademy(name) {
    if (!searchSet) {
      searchSet = new Set();
      const A = window.AcademyAssets;
      if (A && A.searchable) A.searchable.forEach((s) => searchSet.add(String(s).trim()));
    }
    if (!searchSet.size) return false;
    const q = String(name).trim();
    if (searchSet.has(q)) return true;
    // 别名形态也认（「标普 500」vs「标普500」这类）
    for (const s of searchSet) {
      if (s.replace(/\s+/g, '') === q.replace(/\s+/g, '')) return true;
    }
    return false;
  }

  /** 终端 universe 里的 symbol 集合（终端能看的每一只，科普站都要有一页） */
  let uniSet = null;
  function inUniverse(symbol) {
    if (!symbol) return false;
    if (!uniSet) {
      uniSet = new Set();
      const push = (arr) => (arr || []).forEach((x) => uniSet.add(x.symbol));
      push(window.TENCENT_UNIVERSE);
      push(window.EM_UNIVERSE);
    }
    return uniSet.has(symbol);
  }

  /** 科普站有没有这一只的标的页（带真实月线数据卡的那张）
      清单来自 js/data/academy-assets.js（自动同步，勿手抄） */
  let assetSet = null;
  function hasAssetPage(symbol) {
    if (!symbol) return false;
    if (!assetSet) {
      assetSet = new Set();
      const A = window.AcademyAssets;
      if (A && A.symbols) A.symbols.forEach((s) => assetSet.add(s));
    }
    // 清单还没加载进来时**保守地不给**：宁可给搜索页，也不给半空页
    return assetSet.size > 0 && assetSet.has(symbol);
  }

  return { BASE, TERM_BY_SYMBOL, CONCEPT_BY_SYMBOL, targetFor, inUniverse, hasAssetPage };
})();

window.AcademyGloss = AcademyGloss;
;

/* ==== js/academy-gate.js ==== */
/* academy-gate.js —— 科普入口（白话金融）的总开关
   设置里可以整个关掉：关掉后
     · 悬停浮出的「这是什么」不再出现
     · 顶栏的「白话金融 ↗」链接消失
     · 详情页顶栏的「在白话金融里看解释」消失
     · 概念标记不再显示可悬停的光标
   单独放一个模块，是为了这段逻辑能被 node 直接单测（效果全在 DOM 上，断言也全在 DOM 上）。 */
(function () {
  'use strict';

  const BASE = 'https://5777-wq.github.io/openfinlens/';

  /** 当前是否开着（默认开；老用户没存过这项也算开） */
  function isOn() {
    try {
      const s = window.Store && window.Store.settings ? window.Store.settings.get() : null;
      return s ? s.academy !== false : true;
    } catch (e) { return true; }
  }

  /** 把开关状态同步到所有相关 DOM 上；返回最终状态 */
  function apply(on) {
    const v = !!on;
    if (document.body) document.body.dataset.academy = v ? 'on' : 'off';

    const link = document.getElementById('academyLink');
    if (link) link.hidden = !v;

    const gl = document.getElementById('detailGloss');
    if (gl) gl.hidden = !v;

    // ETF 面板里那条「看不懂这些基金」的科普入口，跟顶栏链接一起开关
    const eg = document.getElementById('etfGloss');
    if (eg) eg.hidden = !v;

    const sw = document.getElementById('swAcademy');
    if (sw) {
      sw.classList.toggle('on', v);
      sw.setAttribute('aria-checked', String(v));
    }

    if (window.GlossTip) window.GlossTip.apply(v);
    return v;
  }

  /** 切换并落盘 */
  function toggle() {
    const next = !isOn();
    if (window.Store && window.Store.settings) window.Store.settings.set({ academy: next });
    return apply(next);
  }

  window.AcademyGate = { isOn, apply, toggle, BASE };
})();
;

/* ==== js/technical.js ==== */
/* technical.js —— 技术面指标库（纯函数，无 DOM / 无网络，可直接单测）
   对标 TradingView 常用指标中"免费日K就能算"的一批：
   均线系统(MA5/10/20/60) · EMA(12/26) · MACD(12,26,9) · RSI(14) · KDJ(9,3,3)
   · BOLL(20,2) · ATR(14) · 量比(5日)。
   铁律：只描述事实与常用读法（"超买""金叉""多头排列"），绝不说"建议买入/卖出"；
   数据不足/脏数据一律返回 null，绝不抛异常、绝不产出 NaN 毒化渲染。 */

const Technical = (() => {
  const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
  const clean = (arr) => (Array.isArray(arr) ? arr.filter(isNum) : []);
  const last = (arr) => (arr.length ? arr[arr.length - 1] : null);

  /* ---------- 基础序列 ---------- */
  // 简单均线序列（与 charts.calcMA 同口径：不足 n 处为 null）
  function smaSeries(closes, n) {
    const out = [];
    let sum = 0;
    for (let i = 0; i < closes.length; i++) {
      sum += closes[i];
      if (i >= n) sum -= closes[i - n];
      out.push(i < n - 1 ? null : sum / n);
    }
    return out;
  }

  // EMA 序列：种子 = 前 n 项 SMA，此后 ema = prev + (close - prev) * k, k=2/(n+1)
  function emaSeries(closes, n) {
    if (closes.length < n) return closes.map(() => null);
    const k = 2 / (n + 1);
    const out = [];
    let seed = 0;
    for (let i = 0; i < n; i++) { seed += closes[i]; out.push(null); }
    let prev = seed / n;
    out[n - 1] = prev;
    for (let i = n; i < closes.length; i++) {
      prev = prev + (closes[i] - prev) * k;
      out.push(prev);
    }
    return out;
  }

  /* ---------- 指标 ---------- */
  // RSI(n)：Wilder 平滑
  function rsi(closes, n = 14) {
    const c = clean(closes);
    if (c.length < n + 1) return null;
    let gain = 0, loss = 0;
    for (let i = 1; i <= n; i++) {
      const d = c[i] - c[i - 1];
      if (d >= 0) gain += d; else loss -= d;
    }
    let avgG = gain / n, avgL = loss / n;
    for (let i = n + 1; i < c.length; i++) {
      const d = c[i] - c[i - 1];
      avgG = (avgG * (n - 1) + (d > 0 ? d : 0)) / n;
      avgL = (avgL * (n - 1) + (d < 0 ? -d : 0)) / n;
    }
    if (avgL === 0) return 100;
    return 100 - 100 / (1 + avgG / avgL);
  }

  // MACD(12,26,9)：返回末值 dif/dea/hist + 前值（判金叉死叉）
  function macd(closes, fast = 12, slow = 26, signal = 9) {
    const c = clean(closes);
    if (c.length < slow + signal) return null;
    const ef = emaSeries(c, fast);
    const es = emaSeries(c, slow);
    const dif = c.map((_, i) => (ef[i] !== null && es[i] !== null) ? ef[i] - es[i] : null);
    const difValid = dif.filter(v => v !== null);
    const deaSeq = emaSeries(difValid, signal);
    const pad = dif.length - deaSeq.length;
    const dea = dif.map((_, i) => (i < pad ? null : deaSeq[i - pad]));
    const lastDif = last(dif.filter(v => v !== null));
    const lastDea = last(dea.filter(v => v !== null));
    if (!isNum(lastDif) || !isNum(lastDea)) return null;
    // 前值：倒数第二个有效对
    let prevDif = null, prevDea = null, seen = 0;
    for (let i = dif.length - 1; i >= 0; i--) {
      if (dif[i] !== null && dea[i] !== null) {
        seen++;
        if (seen === 2) { prevDif = dif[i]; prevDea = dea[i]; break; }
      }
    }
    return { dif: lastDif, dea: lastDea, hist: lastDif - lastDea, prevDif, prevDea };
  }

  // KDJ(9,3,3)：RSV→K→D，J=3K-2D，初值 50
  function kdj(klines, n = 9) {
    if (!Array.isArray(klines) || klines.length < n) return null;
    const ks = klines.filter(k => isNum(k.close) && isNum(k.high) && isNum(k.low));
    if (ks.length < n) return null;
    let K = 50, D = 50;
    let prevK = null, prevD = null;
    for (let i = 0; i < ks.length; i++) {
      if (i < n - 1) continue;
      const win = ks.slice(i - n + 1, i + 1);
      const hh = Math.max(...win.map(x => x.high));
      const ll = Math.min(...win.map(x => x.low));
      const rsv = hh === ll ? 50 : (ks[i].close - ll) / (hh - ll) * 100;
      K = (2 * K + rsv) / 3;
      D = (2 * D + K) / 3;
      if (i === ks.length - 2) { prevK = K; prevD = D; }
    }
    return { k: K, d: D, j: 3 * K - 2 * D, prevK, prevD };
  }

  // BOLL(20,2)：中轨 SMA + 总体标准差；%B = 现价在带内位置(0=下轨 1=上轨，可越界)
  function boll(closes, n = 20, k = 2) {
    const c = clean(closes);
    if (c.length < n) return null;
    const win = c.slice(-n);
    const mid = win.reduce((a, b) => a + b, 0) / n;
    const sd = Math.sqrt(win.reduce((s, v) => s + (v - mid) * (v - mid), 0) / n);
    const up = mid + k * sd, low = mid - k * sd;
    const price = last(c);
    return {
      mid, up, low,
      pctB: up === low ? 0.5 : (price - low) / (up - low),
      width: mid !== 0 ? (up - low) / mid * 100 : null,   // 带宽（%价格）
    };
  }

  // ATR(14)：TR 的 Wilder 平滑，返回绝对值与占现价百分比
  function atr(klines, n = 14) {
    if (!Array.isArray(klines) || klines.length < n + 1) return null;
    const ks = klines.filter(k => isNum(k.high) && isNum(k.low) && isNum(k.close));
    if (ks.length < n + 1) return null;
    const trs = [];
    for (let i = 1; i < ks.length; i++) {
      trs.push(Math.max(
        ks[i].high - ks[i].low,
        Math.abs(ks[i].high - ks[i - 1].close),
        Math.abs(ks[i].low - ks[i - 1].close),
      ));
    }
    let v = trs.slice(0, n).reduce((a, b) => a + b, 0) / n;
    for (let i = n; i < trs.length; i++) v = (v * (n - 1) + trs[i]) / n;
    const price = ks[ks.length - 1].close;
    return { value: v, pct: price !== 0 ? v / price * 100 : null };
  }

  // 量比 = 最新成交量 ÷ 前 n 根均量
  function volumeRatio(klines, n = 5) {
    if (!Array.isArray(klines) || klines.length < n + 1) return null;
    const ks = klines.filter(k => isNum(k.volume) && k.volume > 0);
    if (ks.length < n + 1) return null;
    const prevAvg = ks.slice(-(n + 1), -1).reduce((s, k) => s + k.volume, 0) / n;
    return prevAvg > 0 ? ks[ks.length - 1].volume / prevAvg : null;
  }

  // 均线系统：MA5/10/20/60 末值 + 现价与均线关系 + 排列判断
  function maSystem(closes) {
    const c = clean(closes);
    if (c.length < 60) return null;
    const price = last(c);
    const mas = {};
    [5, 10, 20, 60].forEach(n => {
      const seq = smaSeries(c, n);
      mas['ma' + n] = last(seq);
    });
    const above = [5, 10, 20, 60].filter(n => price > mas['ma' + n]).length;
    const bull = mas.ma5 > mas.ma10 && mas.ma10 > mas.ma20 && mas.ma20 > mas.ma60;
    const bear = mas.ma5 < mas.ma10 && mas.ma10 < mas.ma20 && mas.ma20 < mas.ma60;
    return { price, mas, above, trend: bull ? 'bull' : bear ? 'bear' : 'mix' };
  }

  /* ---------- 汇总：事实 + 信号（描述性，不荐股） ---------- */
  // signals: [{ tag, text, bias }] bias: 'up'|'down'|'flat'
  function analyze(klines) {
    if (!Array.isArray(klines) || klines.length < 60) return null;
    const closes = klines.map(k => k.close);
    const price = last(clean(closes));
    const out = { price, signals: [] };

    // 均线系统
    const ma = maSystem(closes);
    out.ma = ma;
    if (ma) {
      out.signals.push(ma.trend === 'bull'
        ? { tag: '均线', text: `多头排列：5>10>20>60 日线自上而下张开，现价站上全部 4 条均线。常用读法：趋势市，回踩均线是观察点。`, bias: 'up' }
        : ma.trend === 'bear'
          ? { tag: '均线', text: `空头排列：5<10<20<60 日线自上而下压住，现价低于全部 4 条均线。常用读法：弱势市，反弹到均线处常见抛压。`, bias: 'down' }
          : { tag: '均线', text: `均线纠缠：现价处于 ${ma.above}/4 条均线上方，短中期方向不一致。常用读法：震荡市，等排列重新张开。`, bias: 'flat' });
    }

    // MACD
    const md = macd(closes);
    out.macd = md;
    if (md) {
      const cross = (md.prevDif !== null && md.prevDea !== null)
        ? (md.prevDif <= md.prevDea && md.dif > md.dea ? 'golden'
          : md.prevDif >= md.prevDea && md.dif < md.dea ? 'dead' : null) : null;
      out.signals.push(cross === 'golden'
        ? { tag: 'MACD', text: `金叉：DIF(${md.dif.toFixed(3)}) 刚上穿 DEA(${md.dea.toFixed(3)})。常用读法：下跌动能衰竭的信号，但在零轴下方出现时可靠性打折。`, bias: 'up' }
        : cross === 'dead'
          ? { tag: 'MACD', text: `死叉：DIF(${md.dif.toFixed(3)}) 刚下穿 DEA(${md.dea.toFixed(3)})。常用读法：上涨动能衰竭的信号，零轴上方出现时同样打折。`, bias: 'down' }
          : md.dif > 0 && md.dea > 0
            ? { tag: 'MACD', text: `零轴上方运行：DIF ${md.dif.toFixed(3)} / DEA ${md.dea.toFixed(3)}，多头市场环境未破坏。`, bias: 'up' }
            : md.dif < 0 && md.dea < 0
              ? { tag: 'MACD', text: `零轴下方运行：DIF ${md.dif.toFixed(3)} / DEA ${md.dea.toFixed(3)}，空头市场环境未改变。`, bias: 'down' }
              : { tag: 'MACD', text: `围绕零轴反复：DIF ${md.dif.toFixed(3)} / DEA ${md.dea.toFixed(3)}，动能方向不明确。`, bias: 'flat' });
    }

    // RSI
    const r = rsi(closes, 14);
    out.rsi = r;
    if (r !== null) {
      out.signals.push(r >= 70
        ? { tag: 'RSI', text: `RSI(14) = ${r.toFixed(0)}：进入通常定义的"超买区"（≥70）。注意：强趋势里 RSI 可以长期停在 70 上方，超买≠马上下跌。`, bias: 'down' }
        : r <= 30
          ? { tag: 'RSI', text: `RSI(14) = ${r.toFixed(0)}：进入通常定义的"超卖区"（≤30）。同理：弱势里可以持续钝化，超卖≠马上反弹。`, bias: 'up' }
          : { tag: 'RSI', text: `RSI(14) = ${r.toFixed(0)}：处于中性区（30-70），${r > 50 ? '偏强半区' : '偏弱半区'}。`, bias: r > 50 ? 'up' : r < 50 ? 'down' : 'flat' });
    }

    // KDJ
    const j = kdj(klines);
    out.kdj = j;
    if (j) {
      out.signals.push(j.j > 100
        ? { tag: 'KDJ', text: `J 值 ${j.j.toFixed(0)} > 100：短线情绪过热，K=${j.k.toFixed(0)} / D=${j.d.toFixed(0)}。J 值对短线拐点敏感，但大涨行情里会连续钝化。`, bias: 'down' }
        : j.j < 0
          ? { tag: 'KDJ', text: `J 值 ${j.j.toFixed(0)} < 0：短线情绪过冷，K=${j.k.toFixed(0)} / D=${j.d.toFixed(0)}。恐慌末段常见，但阴跌里也会反复钝化。`, bias: 'up' }
          : { tag: 'KDJ', text: `K=${j.k.toFixed(0)} / D=${j.d.toFixed(0)} / J=${j.j.toFixed(0)}：${j.k > j.d ? 'K 在 D 上方，短线动能偏向上' : 'K 在 D 下方，短线动能偏向下'}。`, bias: j.k > j.d ? 'up' : 'down' });
    }

    // BOLL
    const b = boll(closes);
    out.boll = b;
    if (b) {
      out.signals.push(b.pctB > 1
        ? { tag: 'BOLL', text: `收盘价突破布林上轨（%B=${b.pctB.toFixed(2)}，带宽 ${b.width.toFixed(1)}%）。常用读法：强势突破或短期过热，看量能是否配合。`, bias: 'up' }
        : b.pctB < 0
          ? { tag: 'BOLL', text: `收盘价跌破布林下轨（%B=${b.pctB.toFixed(2)}）。常用读法：超跌或破位下行，等缩口企稳再判断。`, bias: 'down' }
          : { tag: 'BOLL', text: `价格在带内 %B=${b.pctB.toFixed(2)} 位置（0=下轨 1=上轨），带宽 ${b.width.toFixed(1)}%。带宽收窄常预示变盘临近。`, bias: 'flat' });
    }

    // ATR + 量比（事实条目）
    const a = atr(klines);
    out.atr = a;
    if (a && a.pct !== null) {
      out.signals.push({ tag: 'ATR', text: `ATR(14) = ${a.value.toFixed(2)}（日均波动约 ${a.pct.toFixed(1)}%）。它不是方向指标：止损宽度、仓位大小常用它来定标。`, bias: 'flat' });
    }
    const vr = volumeRatio(klines);
    out.volRatio = vr;
    if (vr !== null) {
      out.signals.push(vr >= 1.5
        ? { tag: '量能', text: `量比 ${vr.toFixed(2)}（vs 5 日均量）：明显放量，价格方向的"认可度"提高，假突破概率下降。`, bias: 'flat' }
        : vr <= 0.7
          ? { tag: '量能', text: `量比 ${vr.toFixed(2)}（vs 5 日均量）：明显缩量，涨跌都缺乏增量资金确认，突破易失败。`, bias: 'flat' }
          : { tag: '量能', text: `量比 ${vr.toFixed(2)}（vs 5 日均量）：量能平常。`, bias: 'flat' });
    }

    // 综合计票（描述性统计，不是评级）
    const up = out.signals.filter(s => s.bias === 'up').length;
    const down = out.signals.filter(s => s.bias === 'down').length;
    out.bias = { up, down, flat: out.signals.length - up - down };
    return out;
  }

  /* ---------- 日K画像（原大师模块的纯数据部分，随板块更名迁入） ----------
     近一年涨跌 / 距 52 周高低点 / 年化波动 / 最大回撤 / 均线偏离：详情页事实弹药 */
  function computeProfile(klines) {
    if (!Array.isArray(klines) || klines.length < 30) return null;
    const closes = klines.map(k => k.close).filter(c => isNum(c) && c > 0);
    if (closes.length < 30) return null;
    const lastClose = closes[closes.length - 1];
    const win = closes.slice(-Math.min(243, closes.length));
    const yearAgo = win[0];
    const high = Math.max(...win);
    const low = Math.min(...win);

    let vol = null;
    if (win.length >= 31) {
      const rets = [];
      for (let i = 1; i < win.length; i++) rets.push(Math.log(win[i] / win[i - 1]));
      const mean = rets.reduce((a, b) => a + b, 0) / rets.length;
      const varr = rets.reduce((s, r) => s + (r - mean) * (r - mean), 0) / rets.length;
      vol = Math.sqrt(varr) * Math.sqrt(243) * 100;
    }

    let peak = win[0], maxDD = 0, hiIdx = 0;
    for (let i = 0; i < win.length; i++) {
      if (win[i] > peak) { peak = win[i]; hiIdx = i; }
      const dd = win[i] / peak - 1;
      if (dd < maxDD) maxDD = dd;
    }

    const ma = (n) => {
      if (closes.length < n) return null;
      const arr = closes.slice(-n);
      return arr.reduce((a, b) => a + b, 0) / arr.length;
    };

    return {
      points: closes.length,
      yearChangePct: (lastClose / yearAgo - 1) * 100,
      offHighPct: (lastClose / high - 1) * 100,
      offLowPct: (lastClose / low - 1) * 100,
      volAnnual: vol,
      maxDDPct: maxDD * 100,                       // 窗口内最大峰谷回撤（≤0）
      barsSinceHigh: win.length - 1 - hiIdx,       // 距 52 周高点过了多少个交易日
      mom20Pct: closes.length > 20 ? (lastClose / closes[closes.length - 21] - 1) * 100 : null,
      ma20: ma(20), ma60: ma(60),
      ma20OffPct: ma(20) !== null ? (lastClose / ma(20) - 1) * 100 : null,
      ma60OffPct: ma(60) !== null ? (lastClose / ma(60) - 1) * 100 : null,
      aboveMA20: ma(20) !== null ? lastClose > ma(20) : null,
      aboveMA60: ma(60) !== null ? lastClose > ma(60) : null,
      high52w: high, low52w: low,
    };
  }

  return { smaSeries, emaSeries, rsi, macd, kdj, boll, atr, volumeRatio, maSystem, analyze, computeProfile };
})();

window.Technical = Technical;
;

/* ==== js/flags.js ==== */
/* flags.js —— 内联 SVG 简化国旗（Windows Chrome 不渲染 emoji 国旗，只能自绘）
   全部为几何简化版（20×14，圆角 2），在小尺寸下以主色/条带/主图案可辨识为准。 */

const Flags = (() => {
  const S = (inner) => `<svg class="flag" viewBox="0 0 20 14" width="20" height="14" aria-hidden="true">${inner}</svg>`;

  // 五角星 path（外接圆半径 r，中心 cx,cy，顶点朝上）
  function star(cx, cy, r, fill) {
    const pts = [];
    for (let i = 0; i < 10; i++) {
      const ang = -Math.PI / 2 + i * Math.PI / 5;
      const rr = i % 2 === 0 ? r : r * 0.4;
      pts.push((cx + rr * Math.cos(ang)).toFixed(2) + ',' + (cy + rr * Math.sin(ang)).toFixed(2));
    }
    return `<polygon points="${pts.join(' ')}" fill="${fill}"/>`;
  }

  const MAP = {
    cn: () => S(`<rect width="20" height="14" fill="#DE2910"/>${star(4.2, 4.4, 2.4, '#FFDE00')}` +
      star(8.6, 2, 0.8, '#FFDE00') + star(10, 4, 0.8, '#FFDE00') + star(10, 6.6, 0.8, '#FFDE00') + star(8.6, 8.4, 0.8, '#FFDE00')),
    us: () => {
      let stripes = '';
      for (let i = 0; i < 7; i++) stripes += `<rect y="${(i * 2).toFixed(1)}" width="20" height="1.1" fill="#B22234"/>`;
      return S(`<rect width="20" height="14" fill="#fff"/>${stripes}<rect width="9" height="7.7" fill="#3C3B6E"/>` +
        [[2, 2], [4.5, 2], [7, 2], [3.2, 3.8], [5.8, 3.8], [2, 5.6], [4.5, 5.6], [7, 5.6]].map(p => `<circle cx="${p[0]}" cy="${p[1]}" r="0.55" fill="#fff"/>`).join(''));
    },
    hk: () => {
      let petals = '';
      for (let i = 0; i < 5; i++) {
        petals += `<ellipse cx="10" cy="5.4" rx="1.5" ry="2.6" fill="#fff" transform="rotate(${i * 72} 10 7)"/>`;
      }
      return S(`<rect width="20" height="14" fill="#DE2910"/>${petals}<circle cx="10" cy="7" r="0.9" fill="#DE2910"/>`);
    },
    jp: () => S(`<rect width="20" height="14" fill="#fff"/><circle cx="10" cy="7" r="3.4" fill="#BC002D"/>`),
    de: () => S(`<rect width="20" height="4.7" fill="#000"/><rect y="4.7" width="20" height="4.7" fill="#DD0000"/><rect y="9.3" width="20" height="4.7" fill="#FFCE00"/>`),
    gb: () => S(`<rect width="20" height="14" fill="#012169"/><path d="M0,0 L20,14 M20,0 L0,14" stroke="#fff" stroke-width="2.6"/><path d="M0,0 L20,14 M20,0 L0,14" stroke="#C8102E" stroke-width="1.1"/><rect x="8.4" width="3.2" height="14" fill="#fff"/><rect y="5.4" width="20" height="3.2" fill="#fff"/><rect x="9.1" width="1.8" height="14" fill="#C8102E"/><rect y="6.1" width="20" height="1.8" fill="#C8102E"/>`),
    fr: () => S(`<rect width="6.7" height="14" fill="#0055A4"/><rect x="6.7" width="6.6" height="14" fill="#fff"/><rect x="13.3" width="6.7" height="14" fill="#EF4135"/>`),
    kr: () => S(`<rect width="20" height="14" fill="#fff"/><path d="M10,3.5 A3.5,3.5 0 0 1 10,10.5 A1.75,1.75 0 0 1 10,7 A1.75,1.75 0 0 0 10,3.5 Z" fill="#CD2E3A" transform="rotate(-25 10 7)"/><path d="M10,3.5 A3.5,3.5 0 0 0 10,10.5 A1.75,1.75 0 0 0 10,7 A1.75,1.75 0 0 1 10,3.5 Z" fill="#0047A0" transform="rotate(-25 10 7)"/><path d="M3.2,2.8 L5.4,4.4 M3.6,2.2 L5.8,3.8" stroke="#000" stroke-width="0.5"/><path d="M14.6,9.6 L16.8,11.2 M15,9 L17.2,10.6" stroke="#000" stroke-width="0.5"/><path d="M3.2,11.2 L5.4,9.6 M3.6,11.8 L5.8,10.2" stroke="#000" stroke-width="0.5"/><path d="M14.6,4.4 L16.8,2.8 M15,5 L17.2,3.4" stroke="#000" stroke-width="0.5"/>`),
    in: () => S(`<rect width="20" height="4.7" fill="#FF9933"/><rect y="4.7" width="20" height="4.7" fill="#fff"/><rect y="9.3" width="20" height="4.7" fill="#138808"/><circle cx="10" cy="7" r="1.7" fill="none" stroke="#000080" stroke-width="0.55"/><circle cx="10" cy="7" r="0.4" fill="#000080"/>`),
    eu: () => {
      let dots = '';
      for (let i = 0; i < 8; i++) {
        const a = i * Math.PI / 4;
        dots += `<circle cx="${(10 + 2.6 * Math.cos(a)).toFixed(2)}" cy="${(7 + 2.6 * Math.sin(a)).toFixed(2)}" r="0.55" fill="#FFCC00"/>`;
      }
      return S(`<rect width="20" height="14" fill="#003399"/>${dots}`);
    },
    coin: () => S(`<circle cx="10" cy="7" r="6.4" fill="#F7931A"/><text x="10" y="10.6" text-anchor="middle" font-size="9" font-weight="700" fill="#fff" font-family="monospace">₿</text>`),
  };

  function flag(code) {
    const f = MAP[code];
    return f ? f() : '';
  }

  return { flag, MAP };
})();

window.Flags = Flags;
;

/* ==== js/bus.js ==== */
/* bus.js —— 轻量事件总线（几十行，不引状态管理框架）
   把 地球 / 事件列表 / K线 / 资金 通过同一套消息连起来：
     Bus.emit('event:select', ev)   选中一条全球事件
     Bus.emit('symbol:open', t)     请求打开标的详情（复用现有 openDetail）
     Bus.emit('chart:event', m)     用户点中K线上的事件 marker
   监听器抛错只吞掉本监听器，不炸整条链。 */

const Bus = (() => {
  const map = new Map();

  function on(evt, fn) {
    if (!map.has(evt)) map.set(evt, []);
    map.get(evt).push(fn);
    return () => off(evt, fn);
  }

  function off(evt, fn) {
    const list = map.get(evt);
    if (!list) return;
    const i = list.indexOf(fn);
    if (i >= 0) list.splice(i, 1);
  }

  function emit(evt, payload) {
    const list = map.get(evt);
    if (!list) return;
    list.slice().forEach(fn => {
      try { fn(payload); } catch { /* 单个监听器坏了不许拖垮别的模块 */ }
    });
  }

  return { on, off, emit };
})();

window.Bus = Bus;
;

/* ==== js/events.js ==== */
/* events.js —— 全球事件数据模型（纯函数，无 DOM / 无网络，可直接单测）
   GlobalEvent 统一结构（前端与采集脚本共用同一份定义）：
   { id, type, title, source, sourceUrl, publishedAt(ms), lat, lng, country,
     importance: 'high'|'med'|'low', relatedSymbols: [内部 symbol] }
   铁律：拿不到的坐标就是 null（列表可见、地球上不画点），绝不编造位置；
   relatedSymbols 只做"标题里明确提到"的映射，不做因果推断。 */

const Events = (() => {

  /* 事件类型 → 终端配色（少量颜色帮分类识别，不搞几十色） */
  const TYPE_META = {
    central_bank: { label: '央行', color: '#5b8def' },
    policy:       { label: '政策', color: '#5b8def' },
    macro:        { label: '宏观', color: '#e0a83c' },
    trade:        { label: '贸易', color: '#D97757' },
    conflict:     { label: '冲突', color: '#e05252' },
    geopolitics:  { label: '地缘', color: '#8a93a6' },
    market:       { label: '市场', color: '#b06ad4' },
    company:      { label: '公司', color: '#4db6ac' },
    disaster:     { label: '灾害', color: '#c97b4a' },
  };

  /* relatedSymbols 字符串 / 标题关键词 → 看板内部 symbol（只映射真实存在的标的） */
  const SYMBOL_ALIASES = [
    { re: /\b(s&p\s*500|spx|sp500)\b/i, sym: 'usINX' },
    { re: /\b(nasdaq|ndx|ixic)\b/i, sym: 'usIXIC' },
    { re: /\b(dow|dji)\b/i, sym: 'usDJI' },
    { re: /\b(hang\s*seng|hsi)\b/i, sym: 'hkHSI' },
    { re: /\b(shanghai\s*composite|sse\s*composite|shcomp)\b|上证指数/i, sym: 'sh000001' },
    { re: /\b(bitcoin|btc)\b/i, sym: 'BTCUSDT' },
    { re: /\b(ethereum|eth)\b/i, sym: 'ETHUSDT' },
    { re: /\b(usdcnh|usdcny|yuan|renminbi)\b|人民币/i, sym: 'EM:133.USDCNH' },
    { re: /\b(gold|xau)\b/i, sym: 'EM:101.GC00Y' },
    { re: /\b(crude|wti|brent|oil\s*price)\b/i, sym: 'EM:102.CL00Y' },
    { re: /\b(10\s*-?\s*year|treasury\s*yield|us10y)\b/i, sym: 'EM:171.US10Y' },
  ];
  // 国家级关联（仅三个有对应指数的市场；标题明确提到国家才挂，不做推断）。
  // US 缩写走大小写敏感校验（与 geo.js 同款教训）：/i 的 \bus\b 会命中小写代词
  // us（"give us a warning"）；带点缩写 u.s. 无歧义，留在 /i 部分。
  const COUNTRY_ALIASES = [
    { re: /\b(china|chinese|beijing|prc)\b/i, sym: 'sh000001' },
    { re: /\b(u\.s|united states|america|washington)\b/i, cs: /\bUS\b|\bUSA\b/, sym: 'usINX' },
    { re: /\b(hong kong)\b/i, sym: 'hkHSI' },
  ];

  function matchSymbols(text) {
    const s = String(text || '');
    if (!s) return [];
    const out = new Set();
    SYMBOL_ALIASES.forEach(a => { if (a.re.test(s)) out.add(a.sym); });
    COUNTRY_ALIASES.forEach(a => { if (a.cs ? (a.cs.test(s) || a.re.test(s)) : a.re.test(s)) out.add(a.sym); });
    return Array.from(out);
  }

  function resolveRelated(list) {
    return Array.isArray(list) ? list.filter(x => typeof x === 'string') : [];
  }

  /* 标题去重键：小写 + 去符号 + 前 10 词 + 全部数字。
     前 8 词曾把"词尾不同"的两条新闻并成一条（"…despite OPEC cuts" vs
     "…despite OPEC output boost" 第 9-10 词才分岔）；数字后缀兜住更长的标题——
     加息 25 还是 50、伤亡 10 还是 100，数字不同就不是同一件事。 */
  function dedupeKey(title) {
    const norm = String(title || '').toLowerCase().replace(/[^a-z0-9\u4e00-\u9fa5]+/g, ' ').trim();
    if (!norm) return '';
    const words = norm.split(/\s+/);
    const nums = [...new Set(words.filter(w => /^\d+$/.test(w)))].sort().join(',');
    return words.slice(0, 10).join(' ') + '|' + nums;
  }

  /* ISO / 'YYYYMMDDTHHMMSSZ' → ms；解析失败返回 null（绝不返回 NaN） */
  function toMs(t) {
    if (t === null || t === undefined || t === '') return null;
    if (typeof t === 'number') return isFinite(t) ? t : null;
    const s = String(t);
    if (/^\d{8}T\d{6}Z$/.test(s)) {
      const y = +s.slice(0, 4), mo = +s.slice(4, 6), d = +s.slice(6, 8);
      const h = +s.slice(9, 11), mi = +s.slice(11, 13), se = +s.slice(13, 15);
      return Date.UTC(y, mo - 1, d, h, mi, se);
    }
    const ms = Date.parse(s);
    return isNaN(ms) ? null : ms;
  }

  /* 'YYYY-MM-DD'（UTC 日期）——日K marker 对齐用 */
  function dayOf(ms) {
    if (ms === null || ms === undefined || isNaN(ms)) return null;
    return new Date(ms).toISOString().slice(0, 10);
  }

  /* 宏观主体 → 相关资产（spec: AssetRelation）。映射是"相关"不是"因果"，
     一律标 RELATED，UI 与直接提及分开渲染。只映射看板里真实存在的标的。 */
  const ENTITY_MAP = [
    { re: /\b(fed|fomc|federal reserve|powell)\b/i, syms: ['usINX', 'usIXIC', 'usDJI', 'EM:171.US10Y', 'EM:101.GC00Y', 'BTCUSDT'] },
    { re: /\b(ecb|european central bank|lagarde)\b/i, syms: ['EM:119.EURUSD'] },
    { re: /\b(pboc|people'?s bank of china)\b/i, syms: ['sh000001', 'EM:133.USDCNH'] },
    { re: /\b(boj|bank of japan)\b/i, syms: [] },
    { re: /\bopec\b/i, syms: ['EM:102.CL00Y'] },
    { re: /\btariff(s)?\b/i, syms: ['sh000001', 'EM:133.USDCNH'] },
  ];

  function matchRelated(text) {
    const s = String(text || '');
    const out = [];
    ENTITY_MAP.forEach(e => { if (e.re.test(s)) e.syms.forEach(sym => { if (!out.includes(sym)) out.push(sym); }); });
    return out.map(sym => ({ sym, rel: 'RELATED' }));
  }

  /* 清洗 + 去重 + 按时间倒序。无效坐标置 null，不猜测。 */
  function normalize(rawList, cap = 260) {
    const seen = new Set();
    const out = [];
    (Array.isArray(rawList) ? rawList : []).forEach(raw => {
      if (!raw || typeof raw.title !== 'string' || !raw.title.trim()) return;
      const publishedAt = toMs(raw.publishedAt);
      if (publishedAt === null) return;
      const key = dedupeKey(raw.title);
      if (key && seen.has(key)) return;
      if (key) seen.add(key);
      // 注：这里原来有一段"政治风险规避"过滤（检查 raw.question 里的中国主权/领导人/台湾关键词），
      // 是段**永不生效的死代码**——事件数据（data/events/global-events.json）根本没有
      // question 字段，raw.question 恒为 undefined。真正生效的那份在 js/polymarket.js
      // 的 POLITICAL_RISK_RE（预测市场板块用），2026-10-20 迁移时旧副本忘了删，这里清掉。
      // 注意 +null === 0：字面 null 必须显式排除，否则"无坐标"会被算成 (0,0) 落在 Null Island
      const hasGeo = raw.lat !== null && raw.lat !== undefined && raw.lat !== '' &&
        raw.lng !== null && raw.lng !== undefined && raw.lng !== '';
      const lat = hasGeo && isFinite(+raw.lat) ? +raw.lat : null;
      const lng = hasGeo && isFinite(+raw.lng) ? +raw.lng : null;
      out.push({
        id: typeof raw.id === 'string' && raw.id ? raw.id : key + '|' + publishedAt,
        type: TYPE_META[raw.type] ? raw.type : 'market',
        title: raw.title.trim(),
        source: typeof raw.source === 'string' ? raw.source : '',
        sourceUrl: /^https?:\/\//i.test(raw.sourceUrl || '') ? raw.sourceUrl : '',
        publishedAt,
        lat, lng,
        country: typeof raw.country === 'string' ? raw.country : null,
        importance: ['high', 'med', 'low'].includes(raw.importance) ? raw.importance : 'med',
        relatedSymbols: resolveRelated(raw.relatedSymbols).concat(
          matchSymbols(raw.title + ' ' + (raw.extra || ''))),
        // 宏观映射（RELATED）：采集层已给的直接采信，否则按标题现算
        relatedAssets: Array.isArray(raw.relatedAssets) && raw.relatedAssets.length
          ? raw.relatedAssets.filter(x => x && typeof x.sym === 'string')
          : matchRelated(raw.title),
      });
    });
    out.sort((a, b) => b.publishedAt - a.publishedAt);
    return out.slice(0, cap);
  }

  /* 地理聚类：bucketDeg ≤ 0 不聚类。同格合并为一个聚合点，
     count = 事件数，代表事件取重要度最高（并列取最新）。 */
  function cluster(events, bucketDeg) {
    const pts = events.filter(e => e.lat !== null && e.lng !== null);
    if (!bucketDeg || bucketDeg <= 0) {
      return pts.map(e => ({ lat: e.lat, lng: e.lng, count: 1, evs: [e], importance: impRank(e.importance), color: typeColor(e.type) }));
    }
    const b = bucketDeg;
    const grid = new Map();
    pts.forEach(e => {
      const k = Math.round(e.lat / b) + ':' + Math.round(e.lng / b);
      if (!grid.has(k)) grid.set(k, []);
      grid.get(k).push(e);
    });
    const out = [];
    grid.forEach(list => {
      list.sort((x, y) => impRank(y.importance) - impRank(x.importance) || y.publishedAt - x.publishedAt);
      const top = list[0];
      out.push({
        lat: top.lat, lng: top.lng, count: list.length, evs: list.slice(0, 12),
        importance: impRank(top.importance), color: typeColor(top.type),
      });
    });
    return out.sort((a, b) => b.count - a.count || b.importance - a.importance);
  }

  function impRank(i) { return i === 'high' ? 3 : i === 'med' ? 2 : 1; }
  function typeColor(t) { return (TYPE_META[t] || TYPE_META.market).color; }
  function typeLabel(t) { return (TYPE_META[t] || TYPE_META.market).label; }

  /* 事件与标的匹配：relatedSymbols 已在 normalize 时解析 */
  function eventsForSymbol(events, symbol) {
    return (events || []).filter(e => e.relatedSymbols.includes(symbol));
  }

  /* K线 marker：日频，时间取 UTC 日期（publishedAt 语义 = 报道见闻时间）
   *
   * marker 上**不画文字**：图表是一年跨度，事件都集中在最近几天，
   * 于是十几个 marker 全挤在图的最右 2% 宽度里。带文字（"地缘""央行"）时
   * 它们互相重叠、还被 price scale 挤成竖排乱码（实测右侧一列"地""地""地…"）。
   * 只留一个带类型色的小圆点就够——点它会弹事件卡，卡里有类型、时间与标题
   * （js/app.js 的 renderChartEventCard），信息不丢。 */
  function toChartEvent(ev) {
    const time = dayOf(ev.publishedAt);
    if (!time) return null;
    return { time, color: typeColor(ev.type), text: '', ev };
  }

  /* 龙虎榜披露日（上海时区，17:00 后算当日，否则回退到上一个工作日）。
     纯 UTC 数学，不依赖本机时区。 */
  function latestLhbDate(nowMs) {
    const SH = 8 * 3600 * 1000;
    const base = (nowMs === undefined ? Date.now() : nowMs) + SH;
    for (let i = 0; i < 7; i++) {
      const d = new Date(base - i * 86400000);
      const wd = d.getUTCDay();
      if (wd >= 1 && wd <= 5 && (i > 0 || d.getUTCHours() >= 17)) {
        return d.toISOString().slice(0, 10);
      }
    }
    return null;
  }

  /* 数据新鲜度：generatedAt 距今超过 maxAge 视为滞后（UI 显示"滞后"角标，不装实时） */
  function isStale(generatedAtMs, maxAgeMs, nowMs) {
    if (!generatedAtMs) return true;
    return ((nowMs === undefined ? Date.now() : nowMs) - generatedAtMs) > maxAgeMs;
  }

  return { TYPE_META, SYMBOL_ALIASES, ENTITY_MAP, matchSymbols, matchRelated, dedupeKey, toMs, dayOf, normalize,
    cluster, impRank, typeColor, typeLabel, eventsForSymbol, toChartEvent,
    latestLhbDate, isStale };
})();

if (typeof window !== 'undefined') window.Events = Events;
if (typeof module !== 'undefined' && module.exports) module.exports = Events;
