    for (let i = 0; i <= 5; i++) modules[i * size + 8] = get(i);
    modules[7 * size + 8] = get(6);
    modules[8 * size + 8] = get(7);
    modules[8 * size + 7] = get(8);
    for (let i = 9; i < 15; i++) modules[8 * size + (14 - i)] = get(i);
