    const dataBytes = [];
    for (const b of blocks) for (let i = 0; i < b.length; i++) dataBytes.push(b[i]);
    // 解析字节模式
    let bitPos = 0;
    const readBits = (n) => {
      let v = 0;
      for (let i = 0; i < n; i++) {
        const byte = dataBytes[bitPos >> 3];
        const bit = (byte >> (7 - (bitPos & 7))) & 1;
        v = (v << 1) | bit;
        bitPos++;
      }
      return v;
    };
