    const vals = [];
    (pane.lines || []).forEach(l => (l.data || []).forEach(d => { if (isNum(d.value)) vals.push(d.value); }));
    (pane.bars || []).forEach(l => (l.data || []).forEach(d => { if (isNum(d.value)) vals.push(d.value); }));
