    const rel = relevantSources(tab);
    const bad = [];
    for (const [k, v] of (items || [])) {
      if (!v || v.ok) continue;
      if (rel && rel.indexOf(k) < 0) continue;   // 与本页无关的源不算
      bad.push(k);
    }
    return bad;
