      if (el.closest('.rv')) continue;               // app.js 的 .rv 已覆盖，别播第二遍
      var r = el.getBoundingClientRect();
      if (!r.height) continue;                       // 隐藏 tab 里的区块：交给 .view 的切换动画
      if (r.top < vh * 0.9) continue;                // 首屏内：不做
